'use strict';
const {createInterpreter, idOf} = require('./pokeca_effect_interpreter');
const interpreter = createInterpreter(require('./pokeca_effect_data'));
function attackOptions(pokemon) {
  if (!pokemon?.officialCardId && !pokemon?.catalogCardId) return null;
  const descriptor = interpreter.describe({players: [{id: 'source', active: pokemon, bench: []}]}, 'source')[0];
  return descriptor.effects.filter(e => e.source.type === 'ATTACK').map(effect => {
    const {record} = interpreter.lookup(pokemon, effect.effectId);
    const text = record.officialText.attacks.find(a => a.name === effect.source.name);
    return {effectId: effect.effectId, name: text.name, damage: Number(text.damage || 0),
      cost: text.cost.map(x => x === '無色' ? 'C' : x)};
  });
}
function damage(game, playerId, target, amount) {
  interpreter.apply(game, {command: 'DAMAGE', amount}, {playerId,
    sourceInstanceId: idOf(game.players.find(p => p.id === playerId).active),
    sourceType: 'POKEMON', actionType: 'ATTACK', targetIds: [idOf(target)]});
}
function refresh(game){interpreter.refresh(game);if(game.referenceEffectValidation)require('./pokeca_reference_effect_runtime').refresh(game);}
function endTurn(game,actor){interpreter.endTurn(game,actor);if(game.referenceEffectValidation)require('./pokeca_reference_effect_runtime').onEndTurn(game,actor);}
module.exports = {...interpreter,refresh,endTurn,attackOptions,damage};

