const clone = value => JSON.parse(JSON.stringify(value));
function createUIPort({getGame, setGame, onChange = () => {}, onSessionChange = () => {}}) {
  let research = getGame()?Research.newLog(getGame()):null;
  const sessionChanged=()=>{try {onSessionChange();return null;}catch(error){return error.message;}};
  const notify=(reason='action')=>{try {onChange({reason});return null;} catch(error){return error.message;}};
  return {
    getSessionId() {return research?.matchId||null;},
    getStatusView() {return EffectView.statuses(getGame());},
    getCardInfo(playerId,instanceId) {return EffectView.cardInfo(getGame(),playerId,instanceId);},
    getActionExplanation(playerId,action) {return MobileAdapter.inspect(getGame(),playerId,action);},
    getHandOptions(playerId,cardId) {return MobileAdapter.handOptions(getGame(),playerId,cardId);},
    getResearchLog() {return clone(research);},
    getResearchStep(sequence) {const step=research.steps.find(x=>x.sequence===sequence);return step?clone(step):null;},
    getResumeSnapshot() {return Snapshot.create(getGame(),research);},
    restoreSession(envelope) {
      try {const saved=Snapshot.validate(envelope);
        // Audit and refresh a candidate before replacing the current authoritative state.
        const candidate=clone(saved.game);Effects.refresh(candidate);
        if(JSON.stringify(candidate)!==JSON.stringify(saved.game))throw Error('保存状態に再計算が必要です。自動補正せず停止しました');
        setGame(candidate);research=clone(saved.research);const viewError=notify('restore');sessionChanged();return {ok:true,...(viewError?{viewError}:{})};
      }catch(error){return {ok:false,stage:'restore',errors:[error.message]};}
    },
    getView(viewerId='you') {return MobileAdapter.view(getGame(),viewerId);},
    getHandActions(playerId,cardId) {return MobileAdapter.handActions(getGame(),playerId,cardId);},
    getPokemonActions(playerId,instanceId) {return MobileAdapter.pokemonActions(getGame(),playerId,instanceId);},
    canDispatch(playerId,action) {return MobileAdapter.accepts(getGame(),playerId,action);},
    getSnapshot() { return clone(getGame()); },
    loadGame(snapshot) {
      const game = clone(snapshot);
      try {Snapshot.validateGame(game);}catch(error){return {ok:false,stage:'load',errors:[error.message]};}
      const audit = Controller.auditCanonicalGame(game);
      if (!audit.ok) return {ok: false, stage: 'load', errors: [...audit.core.errors, ...audit.legality.errors, ...audit.identity.errors]};
      try { Effects.refresh(game); }
      catch (error) { return {ok: false, stage: 'load', errors: [error.message]}; }
      setGame(game); research=Research.newLog(game); const viewError=notify('load');const persistenceError=sessionChanged(); return {ok: true, ...(viewError?{viewError}:{}),...(persistenceError?{persistenceError}:{})};
    },
    dispatch(playerId, action, {origin='HUMAN'}={}) {
      const before=clone(getGame());
      const result = Controller.executeCanonicalAction(getGame(), playerId, action);
      if(before&&Array.isArray(before.players)){
        if(!research)research=Research.newLog(before);
        const entry=Research.append(research,before,getGame(),playerId,action,result);entry.origin=origin;
      }
      const persistenceError=sessionChanged();if(persistenceError)result.persistenceError=persistenceError;
      if (result.ok) {const viewError=notify();if(viewError)result.viewError=viewError;}
      // Never hand mutable authoritative state to a rendering layer.
      return clone(result);
    },
    getEffects(playerId) { return Effects.describe(getGame(), playerId); },
    getChoices(playerId, effectId) { return Effects.choices(getGame(), playerId, effectId); }
  };
}
module.exports = {createUIPort};

